import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d as c,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"多周期与微程序直觉","description":"","frontmatter":{"title":"多周期与微程序直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/multicycle-microcode.md","filePath":"cs/multicycle-microcode.md","lastUpdated":1789023840000}'),p={name:"cs/multicycle-microcode.md"};function h(A,a,m,u,_,B){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="多周期与微程序直觉" tabindex="-1">多周期与微程序直觉 <a class="header-anchor" href="#多周期与微程序直觉" aria-label="Permalink to &quot;多周期与微程序直觉&quot;">​</a></h1><div class="epigraph"><p>把单周期的长组合切成若干拍，每拍共用一块 ALU 或存储器；控制器变成状态机，微程序只是把状态存在 ROM 里。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/control-truth-table">控制器真值表</a>给出单周期组合控制。本课不重填那张表，也不从流水线转发另起。缺口是：单周期 \\(T\\) 被 <code>lw</code> 拖死，<code>add</code> 却闲着。要把一条指令拆成<strong>多拍</strong>，每拍只走一段路径，时钟变快；CPI 大于 1，乘积可能更小。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单周期里指令存储器与数据存储器、ALU 各用一次，但路径串联。缺口是插入临时寄存器（IR、MDR、A、B、ALUOut），让取指、译码/读堆、执行、访存、写回分拍，ALU 与存储器在不同拍复用同一硬件。控制成为<a href="/cs/fsm-control">FSM</a>：现态「取指」转到「译码」再按 opcode 分支。</p><p>微程序：把 FSM 的下一态与控制向量存在控制存储器里，用微 PC 取微指令。直觉上仍是状态机，只是转移表在 ROM 不在门。RISC-V 整数核不必真用微码；复杂 ISA 才需要。本课要的是这层对应，不把历史 CISC 微码写成长综述。</p><h3 id="多周期不是流水线" tabindex="-1">多周期不是流水线 <a class="header-anchor" href="#多周期不是流水线" aria-label="Permalink to &quot;多周期不是流水线&quot;">​</a></h3><p>多周期同一时刻只执行一条指令的一个阶段。流水线多条指令叠在不同阶段，寄存器是流水寄存器，冒险另论。把 IR 当流水线 IF/ID，会提前偷体系结构课。</p><p><span class="marginnote">Patterson/Hennessy 的多周期章用明确状态：Fetch、Decode、Execute、Memory、Writeback。微程序是同一张图的 ROM 实现。Wilkes 的微程序概念作史注，不展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列状态与每拍使能哪些寄存器、ALUSrc 接谁。<code>lw</code> 拍数多于 <code>add</code>。周期 \\(T\\) 覆盖最慢的一拍（通常存储器）。平均 CPI 按指令混合加权。</p>',11)),(e(),n(E,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SC%5B%22%E5%8D%95%E5%91%A8%E6%9C%9F%E9%95%BF%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20BRK%5B%22IR%20%E4%B8%8E%E4%B8%B4%E6%97%B6%E5%AF%84%E5%AD%98%E5%99%A8%E5%88%87%E6%8B%8D%22%5D%0A%20%20BRK%20--%3E%20FSM%5B%22%E6%8E%A7%E5%88%B6%20FSM%22%5D%0A%20%20FSM%20--%3E%20UCODE%5B%22%E5%8F%AF%E9%80%89%EF%BC%9A%E5%BE%AE%E7%A0%81%20ROM%22%5D%0A%20%20FSM%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%BD%AF%E4%BB%B6%E8%B0%83%E7%94%A8%E7%BA%A6%E5%AE%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>硬件变少：一份 ALU、一份存储器口（若指令先锁进 IR）。性能：CPI×\\(T\\) 与单周期 1×\\(T_{\\mathrm{long}}\\) 比较。后课流水线把 CPI 拉回近 1 同时保持短 \\(T\\)，代价是冒险。本课停在非重叠多拍。</p><p>异常可以在确定拍插入「保存 PC、转入口」状态，比单周期更好接——仍留到异常课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现流水、不讲超标量微码。不把 GPU 的 warp 调度当微程序。调用约定是软件层，下一课才讲，尽管 <code>jal</code> 已经能跳。</p><p>后课默认：多周期 CPU 是 FSM 控制器加数据通路寄存器；微程序 = 表驱动的 FSM。软件如何传参，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多周期用状态寄存器把指令拆拍，复用 ALU/存储器。</li><li>控制是 FSM；微码是 FSM 的 ROM 形态。</li><li>与流水线不同：指令不重叠。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；Harris and Harris。</li></ul>',8))])}const P=i(p,[["render",h]]);export{C as __pageData,P as default};
